{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2117-04-04 19:20:00",
      "speaker": "Doctor",
      "text": "Mr. Meléndez, I'm Dr. Reyes. You were brought in by EMS after being found unconscious on a bridge. Do you remember what happened?"
    },
    {
      "turn_number": 2,
      "time": "2117-04-04 19:21:30",
      "speaker": "Patient",
      "text": "I... I don’t know. I was drinking. Woke up cold. They gave me something in the ambulance?"
    },
    {
      "turn_number": 3,
      "time": "2117-04-04 19:23:00",
      "speaker": "Doctor",
      "text": "Yes, they gave you Narcan because they thought you might have overdosed. But your blood sugar was low too—60—so you got some fluids and sugar. You’re responding now, which is good."
    },
    {
      "turn_number": 4,
      "time": "2117-04-04 19:24:30",
      "speaker": "Patient",
      "text": "I just had a few drinks... maybe more than a few. But I’ve done that before. Why so out of it?"
    },
    {
      "turn_number": 5,
      "time": "2117-04-04 19:26:00",
      "speaker": "Doctor",
      "text": "We think it’s a mix of heavy alcohol use and possibly some cocaine in your system. Your labs show acidosis, which means your body is more acidic than it should be—common with intoxication and poor breathing."
    },
    {
      "turn_number": 6,
      "time": "2117-04-04 19:27:30",
      "speaker": "Patient",
      "text": "Cocaine? I used it a while ago, not today. But yeah, I’ve used. My heart’s bad enough as it is."
    },
    {
      "turn_number": 7,
      "time": "2117-04-04 19:29:00",
      "speaker": "Doctor",
      "text": "We know about your heart—dilated cardiomyopathy, atrial fibrillation, and your defibrillator. That’s why we’re watching you closely. But right now, the main issue is the alcohol intoxication and your altered mental state."
    },
    {
      "turn_number": 8,
      "time": "2117-04-04 19:31:00",
      "speaker": "Patient",
      "text": "I feel better now. Can I go? I don’t like hospitals."
    },
    {
      "turn_number": 9,
      "time": "2117-04-04 19:32:30",
      "speaker": "Doctor",
      "text": "Not yet. You were very unresponsive when you arrived. We did a CT scan of your brain and neck to make sure there was no bleeding or fracture. Good news—no injuries."
    },
    {
      "turn_number": 10,
      "time": "2117-04-04 19:34:00",
      "speaker": "Patient",
      "text": "No, I wasn’t hit. Just passed out. I’ve been sleeping on the street. No home, no meds."
    },
    {
      "turn_number": 11,
      "time": "2117-04-04 19:35:30",
      "speaker": "Doctor",
      "text": "I know. And we saw your chest X-ray—no pneumonia or lung issues. But your heart looks enlarged, which we expected. We’re also checking your blood for anemia because you’ve been unwell."
    },
    {
      "turn_number": 12,
      "time": "2117-04-04 19:37:00",
      "speaker": "Patient",
      "text": "Anemia? I feel tired all the time. But it’s hard to eat regular."
    },
    {
      "turn_number": 13,
      "time": "2117-04-04 19:38:30",
      "speaker": "Doctor",
      "text": "That makes sense. We’ll give you some iron and monitor your levels. But more importantly, we’re worried about alcohol withdrawal. You’ve been admitted before for this."
    },
    {
      "turn_number": 14,
      "time": "2117-04-04 19:40:00",
      "speaker": "Patient",
      "text": "I don’t want to shake or see bugs again. Last time was bad. But I can’t stay here long—I’ve got nowhere to go."
    },
    {
      "turn_number": 15,
      "time": "2117-04-04 19:42:00",
      "speaker": "Doctor",
      "text": "We’re starting you on medication to prevent withdrawal—just to keep you safe. You’ll stay overnight so we can monitor you. If you leave now, you could get very sick."
    },
    {
      "turn_number": 16,
      "time": "2117-04-05 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. You made it through the night without withdrawal symptoms. Your breathing’s better, acidosis is improving, and your labs are stabilizing."
    },
    {
      "turn_number": 17,
      "time": "2117-04-05 08:17:00",
      "speaker": "Patient",
      "text": "So I can go? I feel okay now."
    },
    {
      "turn_number": 18,
      "time": "2117-04-05 08:19:00",
      "speaker": "Doctor",
      "text": "Yes, we’re discharging you. But please, try to get back to your cardiologist. Keep your defibrillator checked. And if you want help with alcohol or housing, we can connect you with services."
    },
    {
      "turn_number": 19,
      "time": "2117-04-05 08:21:00",
      "speaker": "Patient",
      "text": "I’ll think about it. Thanks for not kicking me out yesterday."
    },
    {
      "turn_number": 20,
      "time": "2117-04-05 08:23:00",
      "speaker": "Doctor",
      "text": "Take this referral to the shelter clinic. They can help with meds and check your heart. Stay safe, Mr. Meléndez."
    }
  ],
  "summary": {
    "admission_start": "2117-04-04 19:18:00",
    "admission_end": "2117-04-05 09:06:00",
    "summary_paragraph": "Mr. Meléndez, a homeless man with a history of dilated cardiomyopathy, systolic heart failure, atrial fibrillation, and chronic alcohol and cocaine use, was admitted after being found unconscious on a bridge with altered mental status. He was somnolent on arrival, responded partially to Narcan, and had hypoglycemia and hypotension. Initial imaging showed no acute intracranial, cervical spine, or pulmonary pathology. He was managed for acute alcohol intoxication and at risk for withdrawal, for which he received prophylactic treatment. Acidosis improved with supportive care, and anemia was noted. He remained stable overnight, did not develop withdrawal symptoms, and was discharged the following morning with referrals for housing and cardiac follow-up.",
    "problems": [
      "Acute alcoholic intoxication in alcoholism, continuous",
      "Other primary cardiomyopathies",
      "Acidosis",
      "Automatic implantable cardiac defibrillator in situ",
      "Cocaine abuse, unspecified",
      "Atrial fibrillation",
      "Old myocardial infarction",
      "Coronary atherosclerosis of native coronary artery",
      "Personal history of pulmonary embolism",
      "Lack of housing",
      "Anemia, unspecified",
      "Alcohol withdrawal"
    ]
  }
}
